from math import factorial,comb,prod,gcd,isqrt
import sympy as S
from .authoring import maker,finish
from .common import section
q=maker('valuations-divisors',['prime valuations','divisor structure','attainable minima'])
def v(n,p):
 e=0
 while n%p==0:n//=p;e+=1
 return e
def ds(n):return [d for d in range(1,n+1) if n%d==0]
p=[
q(1,r'What is the largest integer e for which $2^e$ divides $50!$?',47,[(25,'Count only even factors.'),(48,'Round a quotient upward.'),(49,'Assume every factor except one contributes a two.'),(46,'Miss the contribution from multiples of thirty-two.')],[r'Count one two from each multiple of 2, an additional one from each multiple of 4, and so on.',r'The exponent is $25+12+6+3+1$.',r'The sum is 47; the next power 64 exceeds 50.'],['A multiple of eight contributes more than one factor of two.','Count its contributions in successive layers.'],'Count prime factors by divisibility layers.',lambda:v(factorial(50),2),level=2),
q(2,r'How many trailing zeros does $100!$ have when written in base 12?',48,[(24,'Use the decimal trailing-zero rule.'),(97,'Count twos without grouping them in pairs.'),(49,'Round half the exponent of two upward.'),(96,'Add the two bottlenecks instead of taking their minimum.')],[r'Each base-12 trailing zero consumes $12=2^2\cdot3$.',r'$v_2(100!)=97$ and $v_3(100!)=48$.',r'The number of complete groups is $\min(\lfloor97/2\rfloor,48)=48$.'],['Factor the base into prime powers.','The least available complete prime-power group limits the count.'],'Find a prime-power bottleneck in a nondecimal base.',lambda:next(k for k in range(101) if factorial(100)%12**(k+1)!=0)),
q(3,r'What is the least positive integer m such that $12!m$ is a perfect square?',231,[(462,'Add a two although its exponent is already even.'),(77,'Miss the odd exponent of three.'),(33,'Miss the odd exponent of seven.'),(11,'Correct only the largest prime.')],[r'The prime exponents in 12! are 10,5,2,1,1 at 2,3,5,7,11.',r'Only the exponents at 3,7,11 are odd; each needs one additional factor.',r'The least multiplier is $3\cdot7\cdot11=231$. All exponents are then even.'],['A square requires every prime exponent to be even.','Correct only the odd exponents.'],'Construct the smallest square-completing multiplier.',lambda:prod(p for p,e in S.factorint(factorial(12)).items() if e%2)),
q(4,r'A positive integer has only the primes 2 and 3 as prime divisors, both occurring, and has exactly 12 positive divisors. What is its least possible value?',72,[(36,'Use exponents producing nine divisors.'),(96,'Choose exponents five and one without comparing alternatives.'),(108,'Put the larger exponent on the larger prime.'),(486,'Choose exponents one and five.')],[r'Write n=2^a3^b with a,b≥1. Then (a+1)(b+1)=12.',r'The possible exponent pairs are (1,5),(2,3),(3,2),(5,1).',r'The corresponding integers are 486,108,72,96, so the minimum is 72.'],['Translate the divisor count into a product of exponent increments.','Compare every admissible exponent pattern.'],'Optimize a number subject to a divisor-count constraint.',lambda:next(n for n in range(1,500) if set(S.factorint(n))=={2,3} and S.divisor_count(n)==12)),
q(5,r'How many positive divisors of 360 are perfect squares?',4,[(24,'Count every divisor.'),(6,'Allow an odd exponent of two.'),(8,'Allow an exponent of two on the prime five.'),(3,'Exclude the divisor one.')],[r'$360=2^3 3^2 5$.',r'A square divisor uses exponent 0 or 2 at both 2 and 3, and exponent 0 at 5.',r'The independent choices give 2·2·1=4, including 1.'],['Factor 360 and restrict exponents to even values.','Zero is an allowed exponent.'],'Count square divisors by exponent choices.',lambda:sum(isqrt(d)**2==d for d in ds(360)),level=2),
q(6,r'What is the sum of the odd positive divisors of 360?',78,[(1170,'Sum all divisors.'),(39,'Omit the divisor factor five.'),(72,'Omit the divisors one and five.'),(13,'Use only the powers of three.')],[r'An odd divisor has no factor of two, so it divides $3^2\cdot5=45$.',r'Its sum factors as $(1+3+9)(1+5)$.',r'The result is 13·6=78; expansion chooses each odd divisor once.'],['Remove the power of two before forming a divisor sum.','A product of geometric sums enumerates independent exponent choices.'],'Restrict a divisor sum before applying multiplicativity.',lambda:sum(d for d in ds(360) if d%2),level=2),
q(7,r'How many positive divisors d of 720 have the property that 720/d is a perfect square?',6,[(30,'Count all divisors.'),(8,'Round each exponent bound upward.'),(5,'Exclude the square quotient one.'),(12,'Allow an odd power of five in the square quotient.')],[r'Mapping d to 720/d is a bijection on positive divisors.',r'$720=2^4 3^2 5$, so square quotients have exponents 0,2,4 at 2; 0,2 at 3; and 0 at 5.',r'There are 3·2·1=6 quotients and therefore six divisors d.'],['Count the quotient instead of the divisor itself.','Explain why the correspondence is one-to-one.'],'Change the counted object through complementary divisors.',lambda:sum(isqrt(720//d)**2==720//d for d in ds(720))),
q(8,r'What is the exponent of 5 in $\binom{100}{40}$?',1,[(24,'Count the numerator factorial only.'),(15,'Subtract only the forty factorial contribution.'),(10,'Subtract only the sixty factorial contribution.'),(0,'Assume denominator cancellation removes all factors of five.')],[r'Use $\binom{100}{40}=100!/(40!60!)$.',r'The valuations are 24,9,14, respectively.',r'Subtracting gives 24-9-14=1. The quotient is an integer, so this is its exact exponent.'],['Express the binomial coefficient as a factorial quotient.','Subtract the prime counts of both denominator factorials.'],'Track cancellation in a factorial ratio.',lambda:v(comb(100,40),5)),
q(9,r'What is the least positive n for which $10^{12}$ divides n!?',50,[(60,'Count just multiples of five.'),(49,'Miss the extra contribution at fifty.'),(48,'Estimate from the exponent of two.'),(55,'Stop at the first multiple of five after the answer.')],[r'Factors of five are the bottleneck; factors of two are more abundant.',r'$v_5(49!)=9+1=10$, while $v_5(50!)=10+2=12$.',r'The valuation is nondecreasing, so 50 is the first admissible n.'],['Determine which prime limits decimal zeros.','Check the jump at a multiple of twenty-five.'],'Prove the first factorial crossing a valuation threshold.',lambda:next(n for n in range(1,100) if factorial(n)%10**12==0)),
q(10,r'How many divisors of $2^{10}3^7$ are divisible by 12 but not by 18?',9,[(63,'Ignore the exclusion of eighteen.'),(18,'Allow two exponents of three.'),(8,'Exclude the largest power of two.'),(11,'Allow divisors missing the required factor four.')],[r'A divisor is $2^a3^b$ with 0≤a≤10 and 0≤b≤7.',r'Divisibility by 12 requires a≥2,b≥1. Since a is already positive, avoiding 18 forces b<2.',r'Thus b=1 and a can be 2 through 10, giving nine choices.'],['Translate both divisibility conditions into exponent inequalities.','Use the first condition to simplify the negation of the second.'],'Count exponent vectors under an inclusion and an exclusion.',lambda:sum((2**a*3**b)%12==0 and (2**a*3**b)%18!=0 for a in range(11) for b in range(8))),
q(11,r'What is the exponent of 2 in the product of all positive divisors of 72?',18,[(3,'Use only the exponent in 72 itself.'),(12,'Report the number of divisors.'),(36,'Pair each divisor twice without compensating.'),(9,'Halve the already paired exponent once more.')],[r'$72=2^3 3^2$ has (3+1)(2+1)=12 divisors.',r'Pair complementary divisors d and 72/d. The six pairs each have product 72.',r'The full product is $72^6$, whose exponent of two is 3·6=18.'],['Pair each divisor with its complement.','Track the prime exponent in the product of each pair.'],'Use complementary-divisor symmetry for a large product.',lambda:v(prod(ds(72)),2)),
q(12,r'How many positive integers n<200 satisfy $\gcd(n,60)=12$?',13,[(16,'Require only divisibility by twelve.'),(12,'Exclude an endpoint that is actually allowed.'),(3,'Count the forbidden multiples of five.'),(10,'Incorrectly require the reduced factor to be coprime to twelve as well.')],[r'Write n=12k. Then gcd(n,60)=12gcd(k,5), so k must not be divisible by five.',r'The bound gives 1≤k≤16.',r'Exclude k=5,10,15 from sixteen candidates to obtain thirteen.'],['Divide both arguments of the gcd by the required common factor.','Apply the upper bound to the reduced variable.'],'Normalize a gcd condition before counting.',lambda:sum(gcd(n,60)==12 for n in range(1,200))),
q(13,r'What is the least positive integer with exactly nine positive divisors?',36,[(24,'Confuse nine divisors with eight.'),(48,'Use an exponent pattern giving ten divisors.'),(256,'Consider only a single-prime power.'),(72,'Use a pattern giving twelve divisors.')],[r'The exponent increments multiply to nine. The possible patterns are n=p^8 or n=p²q² for distinct primes.',r'The smallest first type is 2^8=256; the smallest second type is 2²3²=36.',r'The least overall is 36. These patterns exhaust the factorizations of nine.'],['Factor the desired divisor count into exponent increments.','Compare the smallest number for each possible pattern.'],'Exhaust exponent patterns before choosing a minimum.',lambda:next(n for n in range(1,300) if len(ds(n))==9)),
q(14,r'What is the least positive integer n with exactly twelve positive divisors that is divisible by 18 but not by 4?',90,[(72,'Ignore the exclusion of a second factor of two.'),(108,'Use an otherwise valid divisor pattern with too many factors of two.'),(54,'Choose exponents giving only eight divisors.'),(486,'Consider only the pattern with no prime other than two and three.')],[r'The exponent of two must be exactly one; the exponent b of three is at least two. The remaining divisor-count equation is $(b+1)\prod(c_i+1)=6$.',r'Either b=5 with no other prime, giving 486, or b=2 with one additional prime to the first power. The least possible additional prime is five.',r'The latter gives 2·3²·5=90, which has 2·3·2=12 divisors, is divisible by eighteen, and is not divisible by four.'],['Translate the divisibility and exclusion into prime-exponent restrictions.' ,'Exhaust the ways the remaining exponent increments can multiply to six.'],'Combine a divisor count with divisibility and an excluded prime power.',lambda:next(n for n in range(1,500) if n%18==0 and n%4!=0 and S.divisor_count(n)==12),suffix='-v2')]

e=[
q(101,r'What is the exponent of 2 in $\binom{20}{8}$?',1,[(18,'Use the numerator factorial alone.'),(11,'Omit one denominator factorial.'),(8,'Omit the other denominator factorial.'),(0,'Assume all even factors cancel.')],[r'The binomial coefficient is a factorial quotient, so count prime factors before trying to evaluate the whole number.',r'The valuations of 20!, 8!, and 12! at two are 18,7,10. Subtraction gives one.',r'As a separate check, the coefficient equals 125970, which is divisible by two but not four.',r'The method generalizes because valuations turn products into sums and integer quotients into differences. Always include both denominator factorials.'],['Factorial ratios are easier to analyze prime by prime.','Count multiples of two, four, eight, and sixteen separately.'],'Explain cancellation through valuations.',lambda:v(comb(20,8),2),level=2),
q(102,r'What is the least positive integer n for which 24n is a perfect cube?',9,[(3,'Correct only the exponent of two.'),(6,'Introduce an unnecessary factor of two.'),(18,'Overshoot the required exponent of two.'),(24,'Repeat the original factor without testing exponents.')],[r'Factor 24 as 2³·3. A cube requires every prime exponent to be divisible by three.',r'The exponent of two is already acceptable; the exponent of three needs two more. The least multiplier is 3²=9.',r'Indeed 24·9=216=6³. Any smaller qualifying multiplier would still need to contain 3², which is impossible.',r'This last divisibility observation proves minimality, not just that nine happens to work.'],['Inspect each prime exponent modulo three.','Do not change exponents already divisible by three.'],'Construct and prove a least perfect-power multiplier.',lambda:next(n for n in range(1,100) if all(e%3==0 for e in S.factorint(24*n).values())),level=2)]
finish('valuations-divisors','Prime valuations, divisors & factorials','Number theory','factors integer-constraints congruence-systems',22,'261–290',
 [r'A prime valuation records how many copies of one prime occur in a number. It turns a huge product into a small inventory. Factorials, perfect-power constraints, and divisor counts become questions about those inventories rather than about long decimal integers.',r'The entry examples distinguish two operations: subtracting inventories in a factorial quotient, and completing an inventory to reach a perfect power. In both cases, an exact exponent condition is more informative than the size of the number.'],
 [section('Count repeated factors in layers',r'Among 1 through n, every multiple of p contributes one p, every multiple of p² contributes another, and so on. This gives $v_p(n!)=\lfloor n/p\rfloor+\lfloor n/p^2\rfloor+\cdots$. A multiple of p³ is deliberately counted three times because it contains at least three copies of p.',r'Valuations add under multiplication and subtract under division. For a factorial quotient, compute the numerator and every denominator contribution separately. This can determine divisibility of a binomial coefficient without ever evaluating the coefficient itself.',r'Trailing zeros depend on the base. If the base contains p^a, each zero consumes a copies of p. Divide the available valuation by a and round down; then take the minimum across all primes in the base. Adding these counts has no meaning because a zero needs every required prime simultaneously.'),
 section('Treat divisors as exponent vectors',r'For $n=\prod p_i^{a_i}$, each divisor chooses an exponent from 0 through a_i independently. Hence the count is the product of a_i+1. A square divisor restricts those choices to even exponents, and divisibility by another integer imposes lower bounds.',r'A condition such as divisible by twelve but not eighteen becomes a small logical statement about two exponents. Apply the required condition first, then simplify the forbidden one. This is often shorter and safer than subtracting two broad counts whose intersection has not been identified.',r'Divisor sums factor for the same reason: multiplying the geometric sums of the allowed prime powers chooses each divisor once. For odd divisors, remove the power of two first. For complementary-divisor conditions, map d to n/d and explain why the correspondence is a bijection.'),
 section('Prove minima, not just candidates',r'To minimize a number with a specified divisor count, factor the count into possible exponent increments. Different patterns can compete: nine divisors can mean one eighth power or a product of two squared primes. Exhaust the patterns before choosing the smallest candidate within each.',r'A least perfect-power multiplier corrects each deficient exponent to the next admissible value. Exponents already divisible by the required power need no correction. Show that every qualifying multiplier contains your proposed multiplier as a divisor; this proves minimality directly.',r'For a least factorial index satisfying a threshold, use monotonicity. Check the proposed index and the preceding one. Valuations jump at prime powers, so a rough estimate based only on multiples of p can miss the first crossing. A proof should identify that jump and verify that the other required primes are not the bottleneck.')],
 ['Count exact prime valuations in factorials and quotients.','Translate divisor restrictions into exponent-vector constraints.','Prove least values and nondecimal trailing-zero counts.'],
 [r'Count each p-layer separately to derive the factorial valuation sum.',r'Choose each divisor exponent independently to derive the divisor-count product.',r'For a base containing p^a, divide the available p inventory by a; then take the minimum across primes.'],
 'A divisor count is a product of exponent increments, whereas a valuation is an exponent. Keep these quantities distinct when moving between counting and divisibility.',e,p,
 dict(prompt=r'Find the least positive m for which $72m$ is a perfect cube. Is multiplying by three sufficient? Justify minimality.',answer=r'$m=3$, a factor of three is sufficient: $72\cdot3=216$.',steps=[r'$72=2^3 3^2$; the exponents need corrections zero and one.',r'Every qualifying multiplier must contain a factor of three; hence the working multiplier three is the least.']),
 ['Legendre’s valuation sum','exponent-vector counting','factorial cancellation','prime-power bottlenecks'],
 [(r'v_p(n!)=\sum_{j\ge1}\left\lfloor n/p^j\right\rfloor','Factorial valuation','counting the copies of a prime inside a factorial','p is prime and n is a nonnegative integer; only finitely many terms are nonzero.'),(r'\tau(n)=\prod_i(a_i+1)','Divisor count','counting positive divisors from independent exponent choices','$n=\\prod_i p_i^{a_i}$ is its prime factorization.'),(r'\sigma(n)=\prod_i(1+p_i+\cdots+p_i^{a_i})','Divisor sum','summing positive divisors by expanding independent prime-power choices','The $p_i$ are distinct primes in the factorization of $n$.'),(r'z_B(N)=\min_{p^a\parallel B}\left\lfloor v_p(N)/a\right\rfloor','Trailing-zero bottleneck','counting terminal zeros in an arbitrary integer base','$B\\ge2$ and $N$ is a positive integer; $p^a$ is the full prime power in the base.')], 'factors')
